#!/usr/bin/env node
// render.mjs — render a self-contained HTML visualization to a PNG at an exact
// aspect ratio. Tries, in order:
//   1. Playwright driving installed Chrome, then Edge, then bundled Chromium
//   2. A system Chrome/Chromium/Edge/Brave binary directly (no npm deps)
// and prints the exact fix if none are available.
//
// Usage:
//   node render.mjs --in index.html --out out.png
//   node render.mjs --in index.html --out sq.png --aspect 1:1 --width 1080
//   node render.mjs --in index.html --out big.png --width 2560 --height 1440
//   node render.mjs --in index.html --out t.png --bg transparent --theme dark
//
// Flags:
//   --in <file>        input HTML (required)
//   --out <file>       output PNG (default: <in basename>.png)
//   --aspect <r>       16:9 (default) | 4:3 | 1:1 | 9:16 | 21:9 | 3:2 | 2:1
//   --width <px>       give with --aspect to set size; or with --height for exact
//   --height <px>
//   --scale <n>        device pixel ratio / DPI multiplier (default 2)
//   --theme <t>        light | dark  (passed to the page as ?theme=)
//   --bg <v>           white (default) | transparent | #rrggbb
//   --wait <ms>        max wait for the page's __VIZ_READY__ signal (default 8000)

import { existsSync, mkdirSync } from "node:fs";
import { spawn } from "node:child_process";
import { pathToFileURL } from "node:url";
import { resolve, dirname, basename, extname } from "node:path";
import { platform } from "node:os";

const ASPECTS = { "16:9": 16 / 9, "4:3": 4 / 3, "1:1": 1, "9:16": 9 / 16, "21:9": 21 / 9, "3:2": 3 / 2, "2:1": 2 };

function parseArgs(argv) {
  const a = {};
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i];
    if (k === "--help" || k === "-h") a.help = true;
    else if (k.startsWith("--")) a[k.slice(2)] = argv[i + 1]?.startsWith("--") ? true : argv[++i];
  }
  return a;
}

function die(msg) {
  console.error("✗ " + msg);
  process.exit(1);
}

function help() {
  console.log("render.mjs --in index.html --out out.png [--aspect 16:9] [--width 1600] [--height] [--scale 2] [--theme light|dark] [--bg white|transparent|#hex] [--wait 8000]");
  process.exit(0);
}

function resolveOpts(a) {
  if (a.help) help();
  if (!a.in) die("Missing --in <html file>. Try --help.");
  const inPath = resolve(process.cwd(), a.in);
  if (!existsSync(inPath)) die(`Input not found: ${inPath}`);

  const ratioKey = a.aspect && ASPECTS[a.aspect] ? a.aspect : "16:9";
  if (a.aspect && !ASPECTS[a.aspect]) die(`Unknown --aspect "${a.aspect}". Use one of: ${Object.keys(ASPECTS).join(", ")}`);
  const ratio = ASPECTS[ratioKey];

  let width = a.width ? Math.round(+a.width) : 0;
  let height = a.height ? Math.round(+a.height) : 0;
  if (width && !height) height = Math.round(width / ratio);
  else if (height && !width) width = Math.round(height * ratio);
  else if (!width && !height) { width = 1600; height = Math.round(1600 / ratio); }
  // even dimensions render more predictably
  width += width % 2; height += height % 2;

  const scale = a.scale ? Math.max(1, +a.scale) : 2;
  const waitMs = a.wait ? +a.wait : 8000;
  const theme = a.theme === "dark" || a.theme === "light" ? a.theme : null;
  const bg = a.bg || "white";

  const out = resolve(process.cwd(), a.out || basename(inPath, extname(inPath)) + ".png");
  mkdirSync(dirname(out), { recursive: true });

  let url = pathToFileURL(inPath).href;
  if (theme) url += (url.includes("?") ? "&" : "?") + "theme=" + theme;

  return { inPath, out, url, width, height, scale, waitMs, theme, bg, ratioKey };
}

async function waitReady(page, o) {
  // Prefer the explicit signal the stage template sets; fall back to network
  // idle + a short settle so async charts (Chart.js, etc.) finish painting.
  try {
    await page.waitForFunction("window.__VIZ_READY__ === true", { timeout: o.waitMs });
  } catch {
    await page.waitForLoadState?.("networkidle").catch(() => {});
    await page.waitForTimeout?.(400).catch(() => {});
  }
  await page.evaluate(() => (document.fonts ? document.fonts.ready : null)).catch(() => {});
  await page.waitForTimeout?.(150).catch(() => {});
}

async function renderWithPlaywright(o) {
  let chromium;
  try { ({ chromium } = await import("playwright")); }
  catch { try { ({ chromium } = await import("playwright-core")); } catch { return { ok: false, reason: "no-playwright" }; } }

  // Prefer an already-installed browser channel before the bundled Chromium,
  // so a missing `playwright install` download isn't fatal.
  const attempts = [{ channel: "chrome" }, { channel: "msedge" }, {}];
  let browser, lastErr;
  for (const opt of attempts) {
    try { browser = await chromium.launch({ ...opt, args: ["--force-color-profile=srgb", "--hide-scrollbars"] }); break; }
    catch (e) { lastErr = e; }
  }
  if (!browser) return { ok: false, reason: "launch-failed", error: lastErr };

  try {
    const page = await browser.newPage({ viewport: { width: o.width, height: o.height }, deviceScaleFactor: o.scale });
    await page.goto(o.url, { waitUntil: "load", timeout: 30000 });
    await waitReady(page, o);
    await page.screenshot({
      path: o.out,
      clip: { x: 0, y: 0, width: o.width, height: o.height },
      omitBackground: o.bg === "transparent",
    });
    return { ok: true, via: "playwright" };
  } catch (e) {
    return { ok: false, reason: "render-failed", error: e };
  } finally {
    await browser.close().catch(() => {});
  }
}

function findSystemChrome() {
  const mac = [
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
    "/Applications/Brave Browser.app/Contents/MacOS/Brave Browser",
  ];
  const linux = [
    "/usr/bin/google-chrome", "/usr/bin/google-chrome-stable",
    "/usr/bin/chromium", "/usr/bin/chromium-browser", "/usr/bin/microsoft-edge",
    "/snap/bin/chromium",
  ];
  return (platform() === "darwin" ? mac : linux).find((p) => existsSync(p));
}

function renderWithSystemChrome(bin, o) {
  return new Promise((res) => {
    const args = [
      "--headless=new", "--disable-gpu", "--hide-scrollbars", "--no-sandbox",
      "--force-color-profile=srgb",
      `--force-device-scale-factor=${o.scale}`,
      `--window-size=${o.width},${o.height}`,
      `--screenshot=${o.out}`,
      `--virtual-time-budget=${Math.max(2000, o.waitMs)}`,
      o.bg === "transparent" ? "--default-background-color=00000000" : "--default-background-color=ffffffff",
      o.url,
    ];
    const p = spawn(bin, args, { stdio: "ignore" });
    p.on("error", (error) => res({ ok: false, error }));
    p.on("exit", (code) => res({ ok: code === 0 && existsSync(o.out), via: "system-chrome:" + basename(bin), code }));
  });
}

const INSTALL_HINT = `Could not render: no usable browser found.
Fix with a one-time install:
    npm i -D playwright && npx playwright install chromium
or install Google Chrome (the script will detect and use it automatically).`;

(async () => {
  const o = resolveOpts(parseArgs(process.argv.slice(2)));

  let r = await renderWithPlaywright(o);

  if (!r.ok && (r.reason === "no-playwright" || r.reason === "launch-failed")) {
    const bin = findSystemChrome();
    if (bin) r = await renderWithSystemChrome(bin, o);
  }

  if (!r.ok) {
    if (r.error) console.error(String(r.error.message || r.error));
    die(INSTALL_HINT);
  }

  console.log(`✓ Rendered ${o.width}×${o.height} @${o.scale}× (${o.ratioKey}) → ${o.out}  [${r.via}]`);
})();
